// Shared, static UI markup. User and model text is rendered separately as text nodes.
(() => {
  const composer =
    '          <form id="question-form" class="question-composer">\n            <div id="attachment" class="attachment" hidden>\n              <button\n                id="preview-attachment"\n                class="attachment-preview"\n                type="button"\n                data-title-i18n="previewImage"\n              >\n                <img id="attachment-image" alt="Selected window" /><span\n                  id="attachment-name"\n                ></span></button\n              ><button\n                id="remove-attachment"\n                class="icon-button"\n                type="button"\n                data-title-i18n="removeAttachment"\n                aria-label="Remove screenshot"\n              >\n                ×\n              </button>\n            </div>\n            <textarea\n              id="question"\n              rows="2"\n              maxlength="16000"\n              data-placeholder-i18n="questionPlaceholder"\n              aria-label="Interview question"\n            ></textarea>\n            <div class="composer-actions">\n              <button id="choose-window" type="button" class="composer-tool">\n                <svg><use href="#i-window" /></svg\n                ><span data-i18n="windowSnapshot">Снимок окна</span></button\n              ><button\n                id="paste-question"\n                type="button"\n                class="composer-tool"\n                data-i18n="paste"\n              >\n                Вставить текст</button\n              ><span class="composer-shortcut">⌘ / Ctrl Enter</span\n              ><button id="ask" class="primary" type="submit">\n                <span data-i18n="send">Отправить</span\n                ><svg><use href="#i-arrow" /></svg>\n              </button>\n            </div>\n          </form>';
  const dialogs =
    '        <span id="copy-status" class="sr-only" role="status"></span>\n        <dialog\n          id="window-picker"\n          class="window-dialog"\n          aria-labelledby="picker-title"\n        >\n          <header>\n            <div>\n              <h2 id="picker-title" data-i18n="chooseWindow">Выберите окно</h2>\n              <p class="help" data-i18n="snapshotHint">\n                Будет сделан один снимок. Он отправится вместе со следующим\n                сообщением.\n              </p>\n            </div>\n            <button\n              id="close-picker"\n              class="icon-button"\n              data-title-i18n="close"\n              aria-label="Close"\n            >\n              ×\n            </button>\n          </header>\n          <div id="window-list" class="window-list"></div>\n          <footer>\n            <span id="picker-status" role="status"></span\n            ><button id="refresh-windows" class="secondary" data-i18n="refresh">\n              Обновить\n            </button>\n          </footer>\n        </dialog>\n        <dialog\n          id="image-preview"\n          class="image-dialog"\n          aria-label="Screenshot preview"\n        >\n          <button id="close-image" class="secondary" data-i18n="close">\n            Закрыть</button\n          ><img id="full-image" alt="Window snapshot preview" />\n        </dialog>\n';
  function fragment(markup) {
    const template = document.createElement("template");
    template.innerHTML = markup;
    return template.content;
  }
  document
    .querySelectorAll("[data-composer]")
    .forEach((mount) => mount.replaceWith(fragment(composer)));
  document.body.append(fragment(dialogs));
})();
